inline float mel_filterbank(int mel_idx, int freq_idx) {
  float v;
  memcpy(&v, mel_filterbank_raw + (mel_idx * MFCC_N_FREQ_BINS + freq_idx) * 4, sizeof(float));
  return v;
}

inline float dct_matrix(int mfcc_idx, int mel_idx) {
  float v;
  memcpy(&v, dct_matrix_raw + (mfcc_idx * MFCC_N_MELS + mel_idx) * 4, sizeof(float));
  return v;
}

#endif // MFCC_TABLES_H
